function dateToText(date) {
  const year = date.getFullYear()
  const month = date.getMonth() + 1
  const day = date.getDate()
  let monthText = String(month)
  if (month < 10) {
    monthText = `0${month}`
  }
  let dayText = String(day)
  if (day < 10) {
    dayText = `0${day}`
  }
  return `${year}-${monthText}-${dayText}`
}
